const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function cvmCompanyUrl(code){const value=String(code??'');if(!/^\d{1,6}$/.test(value)||Number(value)===0)return null;const url=new URL('https://www.rad.cvm.gov.br/ENETWeb/frmConsultaExternaCVM.aspx');url.searchParams.set('tipoconsulta','CVM');url.searchParams.set('codigoCVM',String(Number(value)));return url.href;}
function formatRatio(value,percent=false){return Number.isFinite(value)?new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(percent?value*100:value)+(percent?'%':''):'—';}
function historyPoints(rows){return Array.isArray(rows)?rows.filter(r=>Number.isFinite(r.date)&&r.date>0&&Number.isFinite(r.adjustedClose)&&r.adjustedClose>=0).map(r=>({date:r.date,value:r.adjustedClose})).sort((a,b)=>a.date-b.date):[];}
function validateNewsFeed(data){const text=x=>typeof x==='string'&&x.length<=5000;const date=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));const ticker=x=>typeof x==='string'&&/^[A-Z0-9]{4,12}$/.test(x);if(!data||data.version!==1||!Array.isArray(data.items)||!Array.isArray(data.coverage)||data.coverage.some(t=>!ticker(t))||data.updatedAt!==null&&!date(data.updatedAt))throw Error('Arquivo de resumos fora do formato esperado.');for(const n of data.items){let url;try{url=new URL(n.sourceUrl);}catch{throw Error('Fonte do resumo inválida.');}if(url.protocol!=='https:'||!Array.isArray(n.tickers)||n.tickers.some(t=>!ticker(t))||!['title','summary','sourceName','model','uncertainty'].every(k=>text(n[k]))||!date(n.publishedAt)||!date(n.generatedAt)||!Array.isArray(n.facts)||n.facts.some(f=>!f||!text(f.text))||!['positives','negatives'].every(k=>Array.isArray(n[k])&&n[k].every(text)))throw Error('Resumo incompleto ou inválido.');}return {...data,errors:Array.isArray(data.errors)?data.errors:[]};}
function normalizeCatalog(rows){if(!Array.isArray(rows))throw Error('Catálogo inválido');return rows.filter(x=>x&&/^[A-Z0-9]{4,12}$/.test(x.stock)&&['stock','unit','fii'].includes(x.subType)).map(x=>({ticker:x.stock,name:String(x.name||x.stock),type:x.subType==='fii'?'fii':'stock',sector:String(x.subsector||x.sector||'Não informado'),price:Number.isFinite(x.close)&&x.close>=0?x.close:null,change:Number.isFinite(x.change)?x.change:null,volume:Number.isFinite(x.volume)?x.volume:null}));}
function filterAssets(assets,{type='',query='',sector='',sort='ticker',favorites=null}={}){const q=normalize(query.trim());return assets.filter(a=>(!type||a.type===type)&&(!q||normalize(a.ticker+' '+a.name).includes(q))&&(!sector||a.sector===sector)&&(!favorites||favorites.includes(a.ticker))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'pt-BR'):sort==='price'?((b.price??-Infinity)-(a.price??-Infinity)||a.ticker.localeCompare(b.ticker)):sort==='change'?((b.change??-Infinity)-(a.change??-Infinity)||a.ticker.localeCompare(b.ticker)):a.ticker.localeCompare(b.ticker));}

